BEGIN IMMEDIATE;
CREATE TABLE sync_context(id INTEGER PRIMARY KEY CHECK(id=1), suppress INTEGER NOT NULL DEFAULT 0);
INSERT INTO sync_context(id) VALUES(1);
CREATE TABLE sync_identity(id INTEGER PRIMARY KEY CHECK(id=1), device_id TEXT NOT NULL);
INSERT INTO sync_identity VALUES(1,lower(hex(randomblob(32))));
CREATE TABLE sync_pending(kind TEXT NOT NULL,id TEXT NOT NULL,PRIMARY KEY(kind,id));
CREATE TABLE sync_base(kind TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(kind,id));
CREATE TABLE sync_outbox(operation_id TEXT PRIMARY KEY,kind TEXT NOT NULL,id TEXT NOT NULL,base_revision INTEGER NOT NULL,payload TEXT NOT NULL,UNIQUE(kind,id));
CREATE TABLE sync_authority(kind TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(kind,id));
CREATE TABLE sync_log(sequence INTEGER PRIMARY KEY AUTOINCREMENT,kind TEXT NOT NULL,id TEXT NOT NULL,revision INTEGER NOT NULL,payload TEXT NOT NULL);
CREATE TABLE sync_receipts(operation_id TEXT PRIMARY KEY,device_id TEXT NOT NULL,digest TEXT NOT NULL,result TEXT NOT NULL);
CREATE TABLE sync_conflicts(kind TEXT NOT NULL,id TEXT NOT NULL,local_payload TEXT NOT NULL,remote_payload TEXT NOT NULL,remote_revision INTEGER NOT NULL,reason TEXT NOT NULL,PRIMARY KEY(kind,id));
CREATE TABLE sync_client(id INTEGER PRIMARY KEY CHECK(id=1),server_id TEXT NOT NULL DEFAULT '',cursor INTEGER NOT NULL DEFAULT 0);
INSERT INTO sync_client(id) VALUES(1);
INSERT INTO sync_pending SELECT 'expense',id FROM expenses;
INSERT INTO sync_pending SELECT 'document',hash FROM documents;
INSERT INTO sync_pending SELECT 'statement',hash FROM statements;
INSERT INTO sync_pending SELECT 'observation',id FROM observations;
INSERT INTO sync_pending SELECT 'budget','budget' FROM settings WHERE key='budget';
CREATE TRIGGER sync_expense_insert AFTER INSERT ON expenses WHEN (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('expense',NEW.id) ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_expense_update AFTER UPDATE ON expenses WHEN (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('expense',NEW.id) ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_document AFTER INSERT ON documents WHEN (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('document',NEW.hash) ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_statement_insert AFTER INSERT ON statements WHEN (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('statement',NEW.hash) ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_statement_update AFTER UPDATE ON statements WHEN (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('statement',NEW.hash) ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_observation_insert AFTER INSERT ON observations WHEN (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('observation',NEW.id) ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_observation_update AFTER UPDATE OF ignored ON observations WHEN NEW.ignored!=OLD.ignored AND (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('observation',NEW.id) ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_observation_link AFTER UPDATE OF expense_id ON observations WHEN (SELECT suppress FROM sync_context)=0 BEGIN
 INSERT INTO sync_pending SELECT 'expense',OLD.expense_id WHERE OLD.expense_id IS NOT NULL ON CONFLICT(kind,id) DO NOTHING;
 INSERT INTO sync_pending SELECT 'expense',NEW.expense_id WHERE NEW.expense_id IS NOT NULL ON CONFLICT(kind,id) DO NOTHING;
END;
CREATE TRIGGER sync_evidence_insert AFTER INSERT ON evidence WHEN (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('expense',NEW.expense_id) ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_evidence_delete AFTER DELETE ON evidence WHEN (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('expense',OLD.expense_id) ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_budget_insert AFTER INSERT ON settings WHEN NEW.key='budget' AND (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('budget','budget') ON CONFLICT(kind,id) DO NOTHING; END;
CREATE TRIGGER sync_budget_update AFTER UPDATE ON settings WHEN NEW.key='budget' AND (SELECT suppress FROM sync_context)=0 BEGIN INSERT INTO sync_pending VALUES('budget','budget') ON CONFLICT(kind,id) DO NOTHING; END;
PRAGMA user_version=3;
COMMIT;
